function guard_admin(): void { require_role('admin'); }
function geo_svg(array $w, int $h = 40): string {
    $polys = geo_rings(geo_of($w)); if (!$polys) return '<span class="tag plain">Tanpa geometri</span>'; $minX = $minY = INF; $maxX = $maxY = -INF;
    foreach ($polys as $p) foreach ($p[0] as [$x, $y]) { $minX = min($minX, $x); $maxX = max($maxX, $x); $minY = min($minY, $y); $maxY = max($maxY, $y); }
    $k = abs(($minY + $maxY) / 2) <= 90 ? cos(deg2rad(($minY + $maxY) / 2)) : 1; $s = 100 / ((($maxX - $minX) * $k) ?: 1); $H = ($maxY - $minY) * $s ?: 40; $d = '';
    foreach ($polys as $p) foreach ($p as $r) $d .= 'M' . implode('L', array_map(fn($pt) => round(($pt[0] - $minX) * $k * $s + 4, 1) . ' ' . round(($maxY - $pt[1]) * $s + 4, 1), $r)) . 'Z';
    return '<svg viewBox="0 0 108 ' . round($H + 8) . '" style="width:84px;max-height:' . $h . 'px;background:var(--sea);border-radius:8px" aria-hidden="true"><path d="' . $d . '" fill="var(--primary)" fill-opacity=".72" stroke="var(--ink)" stroke-width="1.6" stroke-linejoin="round" fill-rule="evenodd"/></svg>';
}

/* ---------------- Analisis kerawanan ---------------- */
function pg_analisis_post(): void {
    guard_admin(); $aksi = (string) pv('aksi'); $u = current_user();
    if ($aksi === 'jalankan') { if (!tbl('wilayah') || !tbl('parameter')) flash('Tambahkan wilayah dan parameter terlebih dahulu.', 'warn'); else { $r = run_analysis($u['id_pengguna']); flash($r['n'] . ' wilayah dianalisis.' . ($r['skip'] ? ' Dilewati karena belum ada data: ' . implode(', ', $r['skip']) . '.' : ''), $r['skip'] ? 'warn' : 'ok'); } }
    elseif ($aksi === 'rescore') { $n = rescore_all(); flash($n . ' skor data diperbarui. Jalankan analisis ulang untuk memperbarui zona.'); }
    if ($aksi !== '') redirect(url($aksi === 'rescore' && gv('back') ? 'beranda' : 'analisis'));
}
