    $chk = array_slice(data_checks(), 0, 4); $hs = tbl('hasil_kerawanan'); $last = pick_best($hs, fn($x) => $x['tanggal_analisis'] . str_pad((string) $x['id_hasil'], 8, '0', STR_PAD_LEFT));
    $pre = ''; foreach ($chk as $c) $pre .= '<div style="display:grid;grid-template-columns:auto 1fr;gap:10px"><span style="color:' . ($c['ok'] ? 'var(--ok)' : 'var(--warn)') . '">' . ic($c['ok'] ? 'checkc' : 'alert', 20) . '</span><div><b style="font-size:14px">' . e($c['t']) . '</b><div class="muted" style="font-size:13px">' . e($c['d']) . '</div></div></div>';
    $run = '<form method="post" action="' . e(url('analisis')) . '" style="margin:0">' . csrf_field() . '<input type="hidden" name="aksi" value="jalankan"><button class="btn btn-primary" type="submit">' . ic('play', 18) . 'Jalankan analisis</button></form>';
    $h = page_head('Analisis Kerawanan', 'Hitung skor dan tingkat kerawanan setiap wilayah dari data parameter, lalu publikasikan sebagai peta zona kerawanan.', $run)
        . '<div class="grid g-main" style="margin-bottom:18px"><div class="panel"><div class="panel-h"><h2>Alur pengolahan data</h2></div>' . pipeline_html() . '</div><div class="stack"><div class="panel"><div class="panel-h"><h2>Prasyarat analisis</h2></div><div class="list">' . $pre . '</div></div><div class="panel"><div class="panel-h"><h2>Analisis terakhir</h2></div>' . ($last ? '<dl class="kv"><dt>Tanggal</dt><dd>' . fmt_d($last['tanggal_analisis']) . '</dd><dt>Metode</dt><dd>' . e($last['metode']) . '</dd><dt>Dijalankan oleh</dt><dd>' . e(label_of('pengguna', (int) $last['id_pengguna'])) . '</dd></dl>' : '<p class="muted">Belum pernah dijalankan.</p>') . '</div></div></div>'
        . '<div class="panel" style="margin-bottom:18px"><div class="panel-h"><div><h2>Sinkronisasi data BMKG</h2><p>Perbarui parameter angin dari prakiraan BMKG lalu hitung ulang tingkat kerawanan.</p></div></div>' . bmkg_block('admin') . '</div>' . crud_list($cfg);
    return ['title' => 'Analisis Kerawanan', 'html' => $h];
