            if ($v['jumlah_kk'] === null) $v['jumlah_kk'] = 0; $lat = trim((string) ($_POST['titik_lat'] ?? '')); $lng = trim((string) ($_POST['titik_lng'] ?? '')); $desc = trim((string) ($_POST['deskripsi'] ?? ''));
            if (($lat !== '') xor ($lng !== '')) return 'Isi lintang dan bujur titik kampung bersamaan.'; if ($lat !== '' && (!is_numeric($lat) || !is_numeric($lng) || $lat < -12 || $lat > 8 || $lng < 90 || $lng > 145)) return 'Koordinat titik di luar wilayah Indonesia.';
