function pg_wilayah_post(): void {
    guard_admin(); if (pv('aksi') !== 'impor') return; $txt = trim((string) pv('geojson')); $mk = (bool) pv('baru'); $g = json_decode($txt, true);
    $fs = is_array($g) ? (($g['type'] ?? '') === 'FeatureCollection' ? ($g['features'] ?? []) : (($g['type'] ?? '') === 'Feature' ? [$g] : (str_contains((string) ($g['type'] ?? ''), 'Polygon') ? [['type' => 'Feature', 'properties' => [], 'geometry' => $g]] : []))) : [];
    $fs = array_values(array_filter($fs, fn($f) => is_array($f['geometry'] ?? null) && str_contains((string) ($f['geometry']['type'] ?? ''), 'Polygon')));
    if (!$fs) { flash('GeoJSON tidak valid atau tidak berisi poligon.', 'warn'); redirect(url('wilayah', ['impor' => 1])); } $upd = $add = 0; $norm = fn($s) => preg_replace('/[^a-z0-9]/', '', mb_strtolower((string) $s));
    foreach ($fs as $i => $f) { $p = $f['properties'] ?? []; $name = trim((string) ($p['nama'] ?? $p['name'] ?? $p['Name'] ?? $p['NAMA'] ?? $p['nama_wilayah'] ?? $p['NAMOBJ'] ?? $p['WADMKD'] ?? '')); $n = $norm($name); $hit = null;
        if ($n !== '') foreach (tbl('wilayah') as $w) if ($norm($w['nama_wilayah']) === $n) { $hit = $w; break; } if (!$hit && $n !== '') foreach (tbl('wilayah') as $w) { $m = $norm($w['nama_wilayah']); if (str_contains($m, $n) || str_contains($n, $m)) { $hit = $w; break; } }
        $props = ['nama' => $hit['nama_wilayah'] ?? ($name ?: 'Poligon ' . ($i + 1))]; if ($hit) { if (wil_desc($hit)) $props['deskripsi'] = wil_desc($hit); if ($t = wil_titik($hit)) $props['titik'] = [$t[1], $t[0]]; }
        $json = json_encode(['type' => 'Feature', 'properties' => $props, 'geometry' => $f['geometry']], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($hit) { upd('wilayah', $hit['id_wilayah'], ['geometri_geojson' => $json]); $upd++; } elseif ($mk) { ins('wilayah', ['nama_wilayah' => $props['nama'], 'tipe' => 'Permukiman', 'geometri_geojson' => $json, 'jumlah_kk' => 0]); $add++; } }
    flash("$upd geometri diperbarui, $add wilayah baru dibuat."); redirect(url('wilayah'));
}
function pg_wilayah(): array {
    guard_admin();
    if (gv('impor')) return ['title' => 'Data Wilayah', 'html' => page_head('Impor batas wilayah (GeoJSON)', 'Tempel GeoJSON berkoordinat asli (WGS84: bujur, lintang). Gambar poligon tiap wilayah di geojson.io di atas citra satelit, beri properti <span class="mono">nama</span> yang sama dengan nama wilayah, lalu salin isinya ke sini. Data dari QGIS atau batas desa resmi juga bisa dipakai. Titik kampung dan deskripsi tetap dipertahankan.', '<a class="btn" href="' . e(url('wilayah')) . '">Kembali</a>') . '<div class="panel" style="max-width:860px"><form method="post" action="' . e(url('wilayah', ['impor' => 1])) . '">' . csrf_field() . '<input type="hidden" name="aksi" value="impor"><div class="field"><label for="geojson">GeoJSON</label><textarea class="textarea mono" id="geojson" name="geojson" rows="12" spellcheck="false" placeholder=\'{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"nama":"Kampung Peres"},"geometry":{...}}]}\' required></textarea></div><label class="chk" style="margin-bottom:14px"><input type="checkbox" name="baru" value="1"><span>Buat wilayah baru untuk poligon yang namanya tidak cocok (jumlah KK diisi 0, belum dianalisis)</span></label><button class="btn btn-primary" type="submit">' . ic('upload', 18) . 'Impor</button></form></div>'];
    $cfg = wilayah_cfg(); if (($x = crud_action($cfg)) !== null) return ['title' => 'Data Wilayah', 'html' => $x]; $ws = tbl('wilayah'); $ok = count(array_filter($ws, fn($w) => geo_rings(geo_of($w)))); $real = count(array_filter($ws, fn($w) => geo_real($w)));
    return ['title' => 'Data Wilayah', 'html' => page_head('Data Wilayah', 'Kelola daftar wilayah beserta geometri GeoJSON yang menjadi dasar peta zona kerawanan.') . '<div class="grid g4 keep2" style="margin-bottom:18px">' . stat_tile((string) count($ws), 'Wilayah terdaftar') . stat_tile((string) $ok, 'Geometri valid', $real ? $real . ' berkoordinat asli' : 'Semua skematik', 'var(--ok)') . stat_tile(nf(sum(array_column($ws, 'jumlah_kk'))), 'KK per kampung', 'Jumlah tabel di bawah (sensus)', '#3B82C4') . stat_tile((string) count(array_filter($ws, fn($w) => wil_titik($w))), 'Titik kampung', 'Dipakai pada peta satelit', '#8B6F47') . '</div>' . profil_desa_html(true) . '<div style="height:18px"></div>' . crud_list($cfg)];
}

