/* ---------------- Data oseanografi (admin) ---------------- */
function pg_oseanografi_post(): void {
    guard_admin(); if (pv('aksi') !== 'gen') return; if (!pv('konfirmasi')) { flash('Centang konfirmasi untuk mengganti seluruh data.', 'warn'); redirect(url('oseanografi')); }
    db()->exec('DELETE FROM `data_oseanografi`'); tbl_flush('data_oseanografi'); foreach (gen_osea((int) (floor(time() / 3600) * 3600), -24, 48, first_sumber() ?? 1) as $r) ins('data_oseanografi', $r); flash('Data simulasi dibangkitkan.'); redirect(url('oseanografi'));
}
function oseanografi_admin(): array {
