/* ---------------- Peringatan (admin) ---------------- */
function pg_peringatan_post(): void {
    $aksi = (string) pv('aksi');
    if ($aksi === 'timpa' || $aksi === 'cabut') {
        guard_admin(); $u = current_user();
        if ($aksi === 'cabut') { status_set_override(null, $u); flash('Penimpaan dicabut. Status kembali mengikuti perhitungan otomatis.'); redirect(url('peringatan')); }
        $st = (string) pv('status'); $jam = (int) pv('jam'); $al = trim((string) pv('alasan'));
        if (!in_array($st, STATUS_URUT, true) || !in_array($jam, [1, 3, 6, 12, 24], true)) { flash('Pilihan tidak valid.', 'warn'); redirect(url('peringatan')); }
        if (mb_strlen($al) < 10) { flash('Tuliskan alasan minimal 10 karakter. Alasan dicatat dan ditampilkan kepada warga.', 'warn'); redirect(url('peringatan')); }
        status_set_override(['status' => $st, 'alasan' => mb_substr($al, 0, 250), 'berakhir' => time() + $jam * 3600], $u);
        flash('Status ditetapkan ' . $st . ' selama ' . $jam . ' jam dan tercatat atas nama Anda.'); redirect(url('peringatan'));
    }
    if ($aksi !== 'akhiri') return; guard_admin(); $p = row('peringatan', (int) pv('id')); if ($p) { upd('peringatan', $p['id_peringatan'], ['berakhir' => db_dt()]); flash('Peringatan diakhiri.'); } redirect(url('peringatan'));
}
