            return null; },
        'can_delete' => fn($r) => $r['id_pengguna'] === current_user()['id_pengguna'] ? 'Anda tidak dapat menghapus akun yang sedang dipakai.' : ($r['peran'] === 'admin' && count(array_filter(tbl('pengguna'), fn($u) => $u['peran'] === 'admin')) < 2 ? 'Harus tersisa minimal satu administrator.' : null),
        'columns' => [['k' => 'n', 'l' => 'Pengguna', 'v' => fn($r) => $r['nama'], 'f' => fn($r) => '<div style="display:flex;align-items:center;gap:10px"><span class="avatar" style="width:34px;height:34px;font-size:14px;background:' . ROLE_COLOR[$r['peran']] . ';color:#fff">' . e(mb_strtoupper(mb_substr($r['nama'], 0, 1))) . '</span><span><b>' . e($r['nama']) . '</b>' . ($r['id_pengguna'] === current_user()['id_pengguna'] ? ' <span class="tag plain" style="height:20px;font-size:11.5px">Anda</span>' : '') . '<span class="sub">@' . e($r['username']) . '</span></span></div>'], ['k' => 'p', 'l' => 'Peran', 'v' => fn($r) => $r['peran'], 'f' => fn($r) => role_tag($r['peran'])], ['k' => 'a', 'l' => 'Status', 'v' => fn($r) => $r['aktif'] ? 1 : 0, 'f' => fn($r) => $r['aktif'] ? '<span class="tag" style="--c:var(--ok)">Aktif</span>' : '<span class="tag plain">Nonaktif</span>'], ['k' => 'k', 'l' => 'Aktivitas', 'cls' => 'wrap', 'f' => function ($r) { $a = array_filter([[count(where('data_parameter', fn($x) => $x['id_pengguna'] === $r['id_pengguna'])), 'data input'], [count(where('peringatan', fn($x) => $x['id_pengguna'] === $r['id_pengguna'])), 'peringatan'], [count(where('hasil_kerawanan', fn($x) => $x['id_pengguna'] === $r['id_pengguna'])), 'analisis']], fn($x) => $x[0]); return $a ? '<span class="muted">' . e(implode(', ', array_map(fn($x) => $x[0] . ' ' . $x[1], $a))) . '</span>' : '<span class="faint">–</span>'; }]]];
    if (($x = crud_action($cfg)) !== null) return ['title' => 'Pengguna', 'html' => $x];
    $cards = ''; foreach (ROLE_ORDER as $r) $cards .= '<div class="panel" style="border-top:5px solid ' . ROLE_COLOR[$r] . '"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="color:' . ROLE_COLOR[$r] . '">' . ic(roles()[$r]['icon'], 24) . '</span><b class="num" style="font-family:var(--font-display);font-size:26px">' . count(array_filter($us, fn($u) => $u['peran'] === $r)) . '</b></div><h3 style="font-size:16px">' . e(roles()[$r]['label']) . '</h3><p class="muted" style="font-size:13.5px;margin-top:4px">' . e(roles()[$r]['desc']) . '</p><div class="faint" style="font-size:12.5px;margin-top:10px">' . count(menu_items($r)) . ' menu tersedia</div></div>';
    return ['title' => 'Pengguna', 'html' => page_head('Manajemen Pengguna', 'Kelola akun dan peran. Setiap peran memiliki menu dan hak akses yang berbeda, dan hak akses diperiksa di server.') . '<div class="grid g4" style="margin-bottom:18px">' . $cards . '</div>' . crud_list($cfg)];
}

/* ---------------- Skema database (ERD) ---------------- */
function pg_erd(): array {
    guard_admin(); $stroke = ['master' => '#6c8ebf', 'data' => '#82b366', 'proses' => '#d79b00']; $cat = D()['CAT']; $fkOf = []; foreach (rels() as [$p, $c, $col]) $fkOf[$c][$col] = $p;
    $cards = ''; foreach (schema() as $t => $T) { $out = array_filter(rels(), fn($r) => $r[0] === $t); $inc = array_filter(rels(), fn($r) => $r[1] === $t); $n = (int) dbq("SELECT COUNT(*) FROM `$t`")->fetchColumn();
        $cards .= '<article class="panel tight" style="border-top:5px solid ' . $stroke[$T['cat']] . '"><div style="padding:14px 16px 10px;display:flex;align-items:center;justify-content:space-between;gap:8px"><h3 style="display:flex;align-items:center;gap:8px;font-size:17px"><span style="color:' . $stroke[$T['cat']] . '">' . ic($T['icon'], 20) . '</span><span class="mono" style="font-size:14.5px;font-weight:700">' . e($t) . '</span></h3><span class="tag plain num">' . $n . ' baris</span></div><div class="tbl-wrap"><table class="tbl" style="font-size:13px"><tbody>';
        foreach ($T['fields'] as $f) { $isFk = $fkOf[$t][$f['k']] ?? null; $cards .= '<tr><td style="padding:6px 16px;width:36px">' . ($f['t'] === 'pk' ? '<span class="tag" style="--c:#d79b00;height:20px;font-size:11px;padding:0 7px">PK</span>' : ($isFk ? '<span class="tag" style="--c:#6c8ebf;height:20px;font-size:11px;padding:0 7px">FK</span>' : '')) . '</td><td style="padding:6px 8px;' . ($f['t'] === 'pk' ? 'font-weight:700' : '') . '" class="mono">' . e($f['k']) . '</td><td style="padding:6px 16px 6px 8px;text-align:right" class="faint mono">' . e($f['db']) . '</td></tr>'; }
        $cards .= '</tbody></table></div>' . ($out || $inc ? '<div style="padding:10px 16px 14px;font-size:12.5px;color:var(--ink-2);display:grid;gap:3px;border-top:1px solid var(--line)">' . implode('', array_map(fn($r) => '<span style="display:flex;align-items:center;gap:5px;flex-wrap:wrap">' . ic('chevr', 12) . '<b>' . e($r[3]) . '</b> ' . e($r[1]) . ' <span class="faint">(1 ke banyak)</span></span>', $out)) . implode('', array_map(fn($r) => '<span class="faint">dirujuk dari ' . e($r[0]) . ' melalui ' . e($r[2]) . '</span>', $inc)) . '</div>' : '') . '</article>'; }
    $rel = ''; foreach (rels() as $r) $rel .= '<tr><td class="mono"><b>' . e($r[0]) . '</b></td><td>' . e($r[3]) . '</td><td class="mono">' . e($r[1]) . '</td><td class="mono">' . e($r[2]) . '</td><td class="r num">' . (int) dbq("SELECT COUNT(*) FROM `{$r[1]}`")->fetchColumn() . '</td></tr>';
    $leg = ''; foreach ($cat as $k => $v) $leg .= '<span class="it"><span class="sw" style="background:' . $v[1] . ';border-color:' . $stroke[$k] . '"></span>' . e($v[0]) . '</span>';
    return ['title' => 'Skema Database', 'html' => page_head('Skema Database', 'Struktur data aplikasi mengikuti rancangan ERD: ' . count(schema()) . ' tabel dan ' . count(rels()) . ' relasi satu ke banyak, tersimpan di ' . (db_driver() === 'mysql' ? 'MySQL/MariaDB' : 'SQLite') . '. Jumlah baris menampilkan isi basis data saat ini.') . '<div class="legend" style="margin-bottom:18px">' . $leg . '<span class="it faint">PK kunci utama, FK kunci asing</span></div><div class="grid g3" style="align-items:start">' . $cards . '</div><div class="panel tight" style="margin-top:18px"><div class="panel-h" style="padding:18px 20px 0"><h2>Daftar relasi</h2></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Tabel induk (1)</th><th>Relasi</th><th>Tabel anak (banyak)</th><th>Kunci asing</th><th class="r">Baris terhubung</th></tr></thead><tbody>' . $rel . '</tbody></table></div></div>'];
}
